'use strict';

// MODULES //

var tape = require( 'tape' );
var isnan = require( '@stdlib/math/base/assert/is-nan' );
var isAlmostSameValue = require( '@stdlib/assert/is-almost-same-value' );
var polevl = require( './../lib' ); // polevl function from lib/index.js


// FIXTURES //

var data = require( './fixtures/julia/data.json' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof polevl, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function evaluates a polynomial using Horner\'s rule (fixtures)', function test( t ) {
	var expected;
	var actual;
	var coef;
	var x;
	var N;
	var i;

	x = data.x;
	coef = data.coef;
	N = data.N;
	expected = data.expected;

	for ( i = 0; i < x.length; i++ ) {
		actual = polevl( x[ i ], coef[ i ], N[ i ] );
		t.ok( isAlmostSameValue( actual, expected[ i ], 100.0 ), 'within tolerance. x: '+x[ i ]+'. coef: '+JSON.stringify( coef[ i ] )+'. N: '+N[ i ]+'. actual: '+actual+'. expected: '+expected[ i ]+'.' );
	}
	t.end();
});

tape( 'the function returns `NaN` if provided `NaN` for x', function test( t ) {
	var coef = [ 1.0, 2.0, 3.0 ];
	var v = polevl( NaN, coef, 2 );
	t.strictEqual( isnan( v ), true, 'returns NaN' );
	t.end();
});

tape( 'the function throws an error if provided a non-number for x', function test( t ) {
	var coef = [ 1.0, 2.0, 3.0 ];
	t.throws(function foo() {
		polevl( 'abc', coef, 2 );
	}, TypeError, 'throws TypeError');
	t.throws(function foo() {
		polevl( null, coef, 2 );
	}, TypeError, 'throws TypeError');
	t.end();
});

tape( 'the function throws an error if provided a non-collection for coef', function test( t ) {
	var x = 2.0;
	t.throws(function foo() {
		polevl( x, 123, 2 );
	}, TypeError, 'throws TypeError');
	t.throws(function foo() {
		polevl( x, {}, 2 );
	}, TypeError, 'throws TypeError');
	t.end();
});

tape( 'the function throws an error if provided a non-non-negative integer for N', function test( t ) {
	var coef = [ 1.0, 2.0, 3.0 ];
	var x = 2.0;
	t.throws(function foo() {
		polevl( x, coef, 2.5 );
	}, TypeError, 'throws TypeError for float');
	t.throws(function foo() {
		polevl( x, coef, -1 );
	}, TypeError, 'throws TypeError for negative');
	t.throws(function foo() {
		polevl( x, coef, '2' );
	}, TypeError, 'throws TypeError for string');
	t.end();
});

tape( 'the function throws an error if N is out of bounds', function test( t ) {
	var coef = [ 1.0, 2.0, 3.0 ];
	var x = 2.0; // N can be 0, 1, 2
	t.throws(function foo() {
		polevl( x, coef, 3 ); // N=3 is out of bounds (coef.length-1)
	}, RangeError, 'throws RangeError for N >= coef.length');
	t.end();
});
